local k={218,142,252,77,127,227,227,21,124,111,161,43,173,124,208,150,113,102,11,148,19,9,145,100,12,25,96,20,150,212,11,64}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
